{
\paragraph{Verification of \cref{eq:quantum-product-bound}.}
We return to the EPR product $B$ on an arbitrary graph.
Let $F$ be the first parenthesized product
in the definition of $B$. Each factor is Hermitian and positive
definite, with eigenvalues $1$ and $1+\delta p_e/2$. Thus $F$ is
invertible, the reverse product is $F^*$, and $B=FF^*\succ0$.

To bound $B-I-\delta A$, list the matrices $\delta p_eR_e/2$
in their order of occurrence in $B$ as $H_1,\ldots,H_N$, where
$N=2|E|$, and put $h_j\coloneqq\|H_j\|$. Each edge occurs twice, so
\[
 B=\prod_{j=1}^N(I+H_j),\qquad
 \sum_{j=1}^N H_j=\delta A,\qquad
 \sum_{j=1}^N h_j=\delta\sum_e p_e=\delta.
\]
Expand the product by choosing either $I$ or $H_j$ at each position,
keeping the chosen matrices in their original order. The term with no
chosen $H_j$ is $I$, while the terms with exactly one chosen $H_j$
sum to $\sum_jH_j=\delta A$.
Subtracting these terms therefore leaves
\[
 B-I-\delta A
 =\sum_{k=2}^N\;\sum_{1\le i_1<\cdots<i_k\le N}
 H_{i_1}\cdots H_{i_k}.
\]
The norm of a matrix product is at most the product of the norms of its matrices:
\[
 \|H_{i_1}\cdots H_{i_k}\|
 \le\|H_{i_1}\|\cdots\|H_{i_k}\|
 =h_{i_1}\cdots h_{i_k}.
\]
Applying the triangle inequality to the displayed remainder now yields
\begin{align*}
 \|B-I-\delta A\|
 &\le\sum_{k=2}^N\;\sum_{1\le i_1<\cdots<i_k\le N}
       h_{i_1}\cdots h_{i_k}\\
 &=\prod_{j=1}^N(1+h_j)-1-\sum_{j=1}^N h_j\\
 &\le\mathrm{e}^\delta-1-\delta.
\end{align*}
The equality uses the scalar expansion of $\prod_j(1+h_j)$, with
its constant term $1$ and linear terms $\sum_jh_j$ removed. The last
inequality uses $1+h_j\le\mathrm{e}^{h_j}$ and $\sum_jh_j=\delta$.
Similarly, subtracting only $I$ keeps all terms with $k\ge1$, so
\begin{align*}
 \|B-I\|
 &\le\sum_{k=1}^N\;\sum_{1\le i_1<\cdots<i_k\le N}
       h_{i_1}\cdots h_{i_k}\\
 &=\prod_{j=1}^N(1+h_j)-1\le\mathrm{e}^\delta-1.
\end{align*}

Set $D\coloneqq B-I$. Since $\delta\le1/4$, the scalar exponential
series gives
\[
 \mathrm{e}^\delta-1\le\frac{\delta}{1-\delta}\le2\delta,
 \qquad
 \mathrm{e}^\delta-1-\delta\le\frac{\delta^2}{2(1-\delta)}\le\delta^2.
\]
Hence $\|D\|\le2\delta\le1/2$ and $\|D-\delta A\|\le\delta^2$.
Applying the scalar series for $\log(1+x)$ in an orthonormal
eigenbasis of $D$ gives the absolutely convergent matrix series
\begin{align*}
 \log B&=D+\sum_{k=2}^{\infty}\frac{(-1)^{k+1}}{k}D^k,\\
 \|\log B-D\|
 &\le\sum_{k=2}^{\infty}\frac{\|D\|^k}{k}
 \le\frac{\|D\|^2}{2(1-\|D\|)}
 \le4\delta^2.
\end{align*}
Combining the two remainder bounds proves
\[
 \|\log B-\delta A\|
 \le\|\log B-D\|+\|D-\delta A\|
 \le5\delta^2.
\]
This proves \cref{eq:quantum-product-bound} and completes the proof.
\par
}

\label{cor:weighted-contingency-tables}
The input consists of row sums $\bm{r}\in\mathbb Z_{\ge0}^m$,
column sums $\bm{c}\in\mathbb Z_{\ge0}^n$, entrywise upper bounds
$u_{ij}\in\mathbb Z_{\ge0}$, and nonzero nonnegative log-concave
tables $w_{ij}(0),\ldots,w_{ij}(u_{ij})$ with interval support.
There is an $\mathsf{FPRAS}$ for
\begin{align*}
 Z_{\bm{r},\bm{c}}\coloneqq
 \sum_{\substack{X\in\mathbb Z_{\ge0}^{m\times n},\ X_{ij}\le u_{ij}\\
                  \sum_jX_{ij}=r_i\ (i\in[m])\\
                  \sum_iX_{ij}=c_j\ (j\in[n])}}
       \prod_{i=1}^m\prod_{j=1}^n w_{ij}(X_{ij})
\end{align*}
in the arithmetic model of \cref{thm:log-concave-convolution},
provided that $\sum_{i,j}u_{ij}$ and $\log R$ are polynomially
bounded in the input length, where
\begin{align*}
 R\coloneqq\prod_{i=1}^m\prod_{j=1}^n
       \frac{\max_{k:w_{ij}(k)>0}w_{ij}(k)}
            {\min_{k:w_{ij}(k)>0}w_{ij}(k)}.
\end{align*}
Taking $w_{ij}\equiv1$ counts contingency tables with the stated
row sums, column sums, and entrywise upper bounds.

\label{cor:bounded-integer-flows}
Let $B$ be the incidence matrix of a directed graph $(V,E)$, with
outgoing entries $+1$ and incoming entries $-1$. The input consists
of a vector $\bm{h}\in\mathbb Z^V$, capacities $d_a\in\mathbb Z_{\ge0}$,
and nonzero nonnegative log-concave tables $w_a(0),\ldots,w_a(d_a)$
with interval support. Each $h_v$ specifies the required outgoing
flow minus incoming flow at vertex $v$.
There is an $\mathsf{FPRAS}$ for
\begin{align*}
 Z_{\bm{h}}\coloneqq\sum_{\substack{\bm{q}\in\mathbb Z^E,\ B\bm{q}=\bm{h}\\
                           0\le q_a\le d_a}}
                   \prod_{a\in E}w_a(q_a)
\end{align*}
in the arithmetic model of \cref{thm:log-concave-convolution},
provided that $\sum_a d_a$ and $\log R$ are polynomially bounded
in the input length, where
\begin{align*}
 R\coloneqq\prod_{a\in E}
       \frac{\max_{k:w_a(k)>0}w_a(k)}{\min_{k:w_a(k)>0}w_a(k)}.
\end{align*}
Taking $w_a\equiv1$ counts all feasible integer flows.

\label{thm:softintersect-heatbath}
For every ${\mathcal{M}},{\mathcal{N}}$ with $n = \left|{{\mathcal{U}}}\right|\geq1$ and every $\lambda \geq 0$, we have the spectral gap lower bound
\begin{align*}
    \gamma({\mathcal{L}}_{\lambda}) \geq \frac{1}{n \cdot (1 + \lambda) \cdot (1 + \lambda \cdot (n-1))}.
\end{align*}

\label{lem:softintersect-poincare}
For $0 \leq t \leq 1$, define the distribution
\begin{align*}
    \mu_{\lambda}^{(t)}(S) \propto \lambda^{\left|{S}\right|} \cdot t^{\left|{S}\right| - \mathsf{rk}_{{\mathcal{N}}}(S)}, \qquad \forall S \in {\mathcal{I}}({\mathcal{M}}).
\end{align*}
Then for every $f : {\mathcal{I}}({\mathcal{M}}) \to {\mathbb{R}}$, we have the Poincar\'{e} Inequality
\begin{align*}
     \ifthenelse{\isempty{\mu_{\lambda}^{(t)}}}
{\mathbf{Var}\left[f\right]}
{\mathbf{Var}_{\mu_{\lambda}^{(t)}}\left[f\right]}  \leq {\mathcal{E}}_{\lambda}^{(t)}(f,f) \coloneqq \lambda \cdot \sum_{S \in {\mathcal{I}}({\mathcal{M}})} \sum_{\substack{u \notin S \\ S + u \in {\mathcal{I}}({\mathcal{M}})}} \mu_{\lambda}^{(t)}(S) \cdot \left({f(S + u) - f(S)}\right)^{2}.
\end{align*}

The case $\lambda=0$ is trivial so assume $\lambda>0$.
Let $\Omega \coloneqq {\mathcal{I}}({\mathcal{M}})\cap{\mathcal{I}}({\mathcal{N}})$.
For $S\in{\mathcal{I}}({\mathcal{M}})\setminus\Omega$, write
$D_S\coloneqq\{u\in S:S-u\in\Omega\}$ and $d_S\coloneqq|D_S|$.
Fix a function $f:\Omega \to {\mathbb{R}}$.
We extend it to the function $f^{\uparrow}:{\mathcal{I}}({\mathcal{M}}) \to {\mathbb{R}}$ as follow:
\[
 f^{\uparrow}(S)\coloneqq
 \begin{cases}
  f(S), & S\in\Omega,\\[2pt]
  \displaystyle\frac{1}{d_S}\sum_{u\in D_S}f(S-u),
    & S\in{\mathcal{I}}({\mathcal{M}})\setminus\Omega,\ d_S>0,\\[6pt]
  0, & S\in{\mathcal{I}}({\mathcal{M}})\setminus\Omega,\ d_S=0.
 \end{cases}
\]
By \cref{lem:softintersect-poincare} at $t=0$,
\[
  \ifthenelse{\isempty{\mu_\lambda}}
{\mathbf{Var}\left[f\right]}
{\mathbf{Var}_{\mu_\lambda}\left[f\right]}  =  \ifthenelse{\isempty{\mu_\lambda^{(0)}}}
{\mathbf{Var}\left[f^{\uparrow}\right]}
{\mathbf{Var}_{\mu_\lambda^{(0)}}\left[f^{\uparrow}\right]} \le{\mathcal{E}}_\lambda^{(0)}\left({f^{\uparrow},f^{\uparrow}}\right).
\]
We will finish the proof by showing that
\begin{align*}
	{\mathcal{E}}_\lambda^{(0)}\left({f^{\uparrow},f^{\uparrow}}\right)
	&\leq n(1+\lambda) (1 + \lambda(n-1)) \cdot \langle f,{\mathcal{L}}_\lambda f\rangle_{\mu_\lambda}.
\end{align*}
For convenience, put
\[
 {\mathcal{E}}_{\lambda}(f,f)
 \coloneqq
 n(1+\lambda)\langle f,{\mathcal{L}}_\lambda f\rangle_{\mu_\lambda}
 =
 \lambda\sum_{\substack{S\in\Omega,\ u\notin S\\S+u\in\Omega}}
 \mu_\lambda(S)\left({f(S+u)-f(S)}\right)^2.
\]
By the definition of $f^{\uparrow}$,
\begin{align*}
 {\mathcal{E}}_\lambda^{(0)}\left({f^{\uparrow},f^{\uparrow}}\right)
 &={\mathcal{E}}_\lambda(f,f)+
 \lambda\sum_{S\in{\mathcal{I}}({\mathcal{M}})\setminus\Omega}
 \sum_{u\in D_S}
 \mu_\lambda(S-u)\left({f^{\uparrow}(S)-f^{\uparrow}(S-u)}\right)^2\\
 &={\mathcal{E}}_\lambda(f,f)+
 \underset{(\ast)}{\underbrace{\sum_{\substack{S\in{\mathcal{I}}({\mathcal{M}})\setminus\Omega\\d_S\ge2}}
 \frac{\lambda}{d_S}
 \sum_{\{u,v\}\subseteq D_S}
 \mu_\lambda(S-u)\left({f(S-u)-f(S-v)}\right)^2}}.
\end{align*}
In the last equality, we used that for any probability measure $\zeta$ on a domain $\Omega$ and any test function $\varphi : \Omega \to {\mathbb{R}}$, we have $ \ifthenelse{\isempty{\omega \sim \zeta}}
{\mathbf{Var}\left[\varphi(\omega)\right]}
{\mathbf{Var}_{\omega \sim \zeta}\left[\varphi(\omega)\right]}  = \frac{1}{2} \cdot  \ifthenelse{\isempty{\omega,\omega' \sim \zeta}}
  {\mathbb{E}\left[\left({\varphi(\omega) - \varphi(\omega')}\right)^{2}\right]}
  {\mathbb{E}_{\omega,\omega' \sim \zeta}\left[\left({\varphi(\omega) - \varphi(\omega')}\right)^{2}\right]} $.
The inner sum is over unordered pairs of distinct elements;
its summand is symmetric because
$\mu_\lambda(S-u)=\mu_\lambda(S-v)$.

We control $(\ast)$ by a multiple by ${\mathcal{E}}_{\lambda}(f,f)$. To do this, observe that for each $S \in {\mathcal{I}}({\mathcal{M}}) \setminus \Omega$ with $d_{S} \geq 2$ and each pair $\{u,v\} \subseteq D_{S}$, its contribution to $(\ast)$ can be viewed as a ``swap'' move that transitions from $S-u$ to $S-v$. This swap can be simulated using two steps of Glauber dynamics $P_{\lambda}$, namely $S - u \to S - u - v$ followed by $S - u - v \to S - v$. With this intuition in mind, we invoke the numerical inequality $(a-b)^2\le2((a-c)^2+(b-c)^2)$ and
$\mu_\lambda(S-u)=\lambda\mu_\lambda(S-u-v)$ to obtain
\begin{align*}
 (\ast)
 &\le
 \sum_{\substack{S\in{\mathcal{I}}({\mathcal{M}})\setminus\Omega\\d_S\ge2}}
 \frac{2\lambda^2}{d_S}
 \sum_{\substack{u,v\in D_S\\u\ne v}}
 \mu_\lambda(S-u-v)\left({f(S-u)-f(S-u-v)}\right)^2\\
 &\le\lambda^2
 \sum_{\substack{T\in\Omega,\ v\notin T\\T+v\in\Omega}}
 (n-|T|-1)\mu_\lambda(T)\left({f(T+v)-f(T)}\right)^2
 \tag{Setting $T = S - u - v$ and using $d_{S} \geq 2$}\\
 &\le\lambda(n-1){\mathcal{E}}_\lambda(f,f).
 \tag{\(|T|\ge0\)}
\end{align*}
This finishes the proof.
